code='''from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors=set(v for row in grid for v in row if v!=bg)
    candidates=[]
    for color in colors:
        # 2-D prefix sum for fast rectangle counts
        p=[[0]*(w+1) for _ in range(h+1)]
        for r in range(h):
            for c in range(w):
                p[r+1][c+1]=p[r][c+1]+p[r+1][c]-p[r][c]+(grid[r][c]==color)
        for y0 in range(h):
            for y1 in range(y0+1,h):
                for x0 in range(w):
                    for x1 in range(x0+1,w):
                        area=(y1-y0+1)*(x1-x0+1)
                        if area<4: continue
                        n=p[y1+1][x1+1]-p[y0][x1+1]-p[y1+1][x0]+p[y0][x0]
                        if n/area>=0.80:
                            candidates.append((area,n,color,y0,y1,x0,x1))
    candidates.sort(reverse=True)
    chosen=[]
    for area,n,color,y0,y1,x0,x1 in candidates:
        # Keep the largest near-solid object rectangles, without overlap.
        if any(not (y1<a or b<y0 or x1<c or d<x0) for a,b,c,d,_ in chosen): continue
        chosen.append((y0,y1,x0,x1,color))
    out=[[bg]*w for _ in range(h)]
    for y0,y1,x0,x1,color in chosen:
        for y in range(y0,y1+1):
            for x in range(x0,x1+1): out[y][x]=color
    return out
